const Playground = args => {
    const [, updateArgs] = useArgs();

    return (
        <div className="flex flex-col items-start gap-4">
            <LifeHashAvatar fingerprint="a1b2c3d4e5f6" ringed className="size-24 rounded-full" />
            <div className="flex items-center gap-3">
                <button
                    type="button"
                    onClick={() => updateArgs({ fingerprint: randomFingerprint() })}
                    className="rounded-lg border border-white/15 bg-white/5 px-3 py-1.5 text-sm text-white/80 transition-colors hover:bg-white/10">Randomize
                              </button>
                <code className="font-mono text-xs text-white/45">{args.fingerprint}</code>
            </div>
        </div>
    );
};
